def P(v):
 v=v.decode() if isinstance(v,bytes) else v
 assert len(v)==2 and all('a'<=x<='s' for x in v)
 return ord(v[0])-97,ord(v[1])-97

def nb(p):
 x,y=p
 return [q for q in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)) if 0<=q[0]<19 and 0<=q[1]<19]

def chain(b,p):
 c=b[p];z={p};s=[p]
 while s:
  q=s.pop()
  for n in nb(q):
   if b.get(n)==c and n not in z:z.add(n);s.append(n)
 return z

def libs(b,z):return {n for q in z for n in nb(q) if n not in b}
def play(b,c,p):
 assert p not in b,('occupied',c,p)
 b=dict(b);b[p]=c;o='W' if c=='B' else 'B'
 for n in nb(p):
  if b.get(n)==o:
   z=chain(b,n)
   if not libs(b,z):
    for q in z:b.pop(q)
 assert libs(b,chain(b,p)),('suicide',c,p)
 return b

for fn in exp:
 data=(OUT/fn).read_bytes();g=sgf.Sgf_game.from_bytes(data);r=g.get_root();rp=set(r.properties())
 assert r.get('SZ')==19 and {'AB','AW'}<=rp and not {'B','W','C'}&rp
