   raw=ch.get_raw(c);assert raw not in (None,b'');p=P(raw);coord=raw.decode();np=play(bd,c,p);key=frozenset(np.items())
   assert len(hist)<2 or key"'!=hist[-2],(fn,path,'"'ko')
   nodes+=1;depth=max(depth,d+1)
   com=ch.get_raw('C').decode() if 'C' in props else ''
   rights+=('RIGHT' in com)
   stack.append((ch,np,'W' if c=='B' else 'B',d+1,hist+[key],path+[c+coord]))
